"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { useEffect, useId, useRef, useState, useTransition } from "react";
import { Check, LoaderCircle, Plus } from "lucide-react";
import { useRouter } from "next/navigation";
import { addToShortlist, addContactToShortlist } from "@/lib/actions";
import { Button } from "@/components/ui/button";
import { Feedback } from "@/components/forms";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import type { ActionResult } from "@/lib/errors";
import styles from "./contacts.module.css";

function positionTooltip(trigger: HTMLElement, tip: HTMLElement) {
  const box = trigger.getBoundingClientRect();
  const width = tip.getBoundingClientRect().width;
  tip.style.left = `${Math.max(8, Math.min(box.right - width, window.innerWidth - width - 8))}px`;
  tip.style.top = `${Math.max(8, box.top - tip.offsetHeight - 6)}px`;
}

export function ContactShortlistAction({
  sendId,
  contactId,
  inShortlist,
  blocked,
  active,
  iconOnly = false,
  previouslySent = false,
}: {
  inShortlist: boolean;
  blocked: boolean;
  active: boolean;
  iconOnly?: boolean;
  previouslySent?: boolean;
} & (
  { sendId: string; contactId?: never } | { contactId: string; sendId?: never }
)) {
  const access = useWorkspaceEntitlements();
  const upgrade = usePremiumUpgrade();
  const lockId = useId();
  const repeatLocked = sendId
    ? !access.features.historyShortlist
    : previouslySent && !access.features.manualRepeatSend;
  const lockMessage = sendId
    ? "Add from History with Premium. On Free, enter and save this person’s details in Contacts to email them again."
    : "Repeat sending is currently unavailable.";
  const [result, setResult] = useState<ActionResult>();
  const [pending, start] = useTransition();
  const router = useRouter();
  const added = inShortlist;
  const unavailable =
    repeatLocked &&
    (sendId
      ? access.reasons.historyShortlist
      : access.reasons.manualRepeatSend) !== "UPGRADE_REQUIRED";
  const disabled = unavailable || pending || added || blocked || !active;
  const label = added
    ? "In shortlist"
    : pending
      ? "Adding…"
      : "Add to shortlist";
  const tooltipId = useId();
  const tooltip = useRef<HTMLSpanElement>(null);
  const trigger = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (!iconOnly) return;
    const reposition = () => {
      if (trigger.current && tooltip.current?.matches(":popover-open"))
        positionTooltip(trigger.current, tooltip.current);
    };
    window.addEventListener("scroll", reposition, true);
    window.addEventListener("resize", reposition);
    return () => {
      window.removeEventListener("scroll", reposition, true);
      window.removeEventListener("resize", reposition);
    };
  }, [iconOnly]);

  function showTooltip() {
    if (!iconOnly || !tooltip.current || !trigger.current) return;
    const tip = tooltip.current;
    // A popover stays above both the table's clipping and the modal dialog.
    tip.showPopover();
    positionTooltip(trigger.current, tip);
  }

  function hideTooltip() {
    if (
      !trigger.current?.matches(":hover") &&
      !trigger.current?.contains(document.activeElement)
    )
      tooltip.current?.hidePopover();
  }

  return (
    <div className="max-w-56">
      {repeatLocked && (
        <p id={lockId} className="text-xs text-body">
          {lockMessage}
        </p>
      )}
      <span
        ref={trigger}
        className={`inline-flex ${iconOnly ? styles.shortlistTrigger : ""}`}
        tabIndex={iconOnly && disabled ? 0 : undefined}
        aria-describedby={iconOnly && disabled ? tooltipId : undefined}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        onFocus={showTooltip}
        onBlur={hideTooltip}
        onKeyDown=[REDACTED_SECRET]
          if (event.key === "Escape") tooltip.current?.hidePopover();
        }}
      >
        <Button
          type="button"
          variant="outline"
          size={iconOnly ? "icon" : "default"}
          className={iconOnly ? "rounded-lg cursor-pointer" : "cursor-pointer"}
          aria-label={iconOnly ? label : undefined}
          aria-describedby={
            repeatLocked ? lockId : iconOnly ? tooltipId : undefined
          }
          aria-busy={pending || undefined}
          disabled={disabled}
          onClick={() => {
            if (repeatLocked) {
              tooltip.current?.hidePopover();
              upgrade({ feature: sendId ? "shortlist" : "repeat" });
              return;
            }
            start(async () => {
              try {
                setResult(
                  await (contactId
                    ? addContactToShortlist(contactId)
                    : addToShortlist(sendId!)),
                );
                router.refresh();
              } catch {
                setResult({
                  ok: false,
                  message: "Could not add this person. Try again.",
                });
              }
            });
          }}
        >
          {iconOnly ? (
            added ? (
              <Check aria-hidden="true" />
            ) : pending ? (
              <LoaderCircle
                aria-hidden="true"
                className="animate-spin motion-reduce:animate-none"
              />
            ) : (
              <Plus aria-hidden="true" />
            )
          ) : (
            label
          )}
        </Button>
        {iconOnly && (
          <span
            ref={tooltip}
            id={tooltipId}
            role="tooltip"
            popover="manual"
            className="pointer-events-none fixed m-0 w-max rounded-md border-0 bg-foreground px-2 py-1 text-xs text-background shadow-sm"
          >
            {repeatLocked ? lockMessage : label}
          </span>
        )}
      </span>
      {blocked && <p className="mt-2 text-xs text-body">Pending delivery</p>}
      {!active && <p className="mt-2 text-xs text-body">Contact unavailable</p>}
      {result?.ok === false && <Feedback result={result} planLabel="Premium" />}
    </div>
  );
}
